class I:
 def __init__(self): self.n=0
 def __iter__(self): return self
 def __next__(self):
  self.n+=1
  if self.n==1: raise StopIteration("source")
  return self.n
i=map(abs,I())
try: next(i)
except StopIteration as e: print(str(e))
print(next(i))

class I:
 def __init__(self): self.n=0
 def __iter__(self): return self
 def __next__(self):
  self.n+=1
  if self.n==1: raise ValueError("source")
  return -self.n
i=map(abs,I(),strict=True)
try: next(i)
except ValueError as e: print(str(e))
print(next(i))

